// xhs-count —— 小红书字数哨兵
// 选中一段文字，prompt 上方的 band 实时告诉你：
// 够不够标题（≤20 字）、适不适合正文（≤1000 字）、超了几个字要删。

const LIMIT_TITLE = 20
const LIMIT_BODY = 1000
const POLL_MS = 800

// 上一次统计到的选区与结果
let lastText = ''
let lastStats = null

function statsFor(text) {
  // 中文按 Unicode 码点数，emoji 也算一个字
  const count = [...text].length
  if (count <= LIMIT_TITLE) {
    return {
      count,
      label: `够标题（≤${LIMIT_TITLE}），还差 ${LIMIT_TITLE - count} 字拉满悬念`,
      color: 'green',
    }
  }
  if (count <= LIMIT_BODY) {
    return {
      count,
      label: `适合正文，已用 ${count}/${LIMIT_BODY}`,
      color: 'yellow',
    }
  }
  return {
    count,
    label: `正文超了 ${count - LIMIT_BODY} 字，删！`,
    color: 'red',
  }
}

export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'xhs-count',
      description: '小红书字数哨兵：选中文字，band 实时统计够不够标题/正文',
    })
    // 定时轮询选区；$.ui.selection() 在 fullscreen 下返回最近选中的文字
    $.clock.every(POLL_MS, async () => {
      try {
        const sel = await $.ui.selection()
        const text = typeof sel === 'string' ? sel : (sel?.text ?? '')
        if (!text || text === lastText) return
        lastText = text
        lastStats = statsFor(text)
        $.ui.invalidate('ui.render')
      } catch {
        // 选区不可用时保持上一次结果
      }
    })
    return next(e)
  })

  // 常驻 band：prompt 上方那条
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const { Box, Text } = $.ui.resolve(e)
    if (!lastStats) {
      return Box({ flexDirection: 'row', children: [
        Text({
          children: ['🔍 xhs字数哨兵 · 全屏选中一段文字，我帮你卡标题（≤20）/正文（≤1000）字数'],
          dimColor: true,
        }),
      ]})
    }
    return Box({ flexDirection: 'row', columnGap: 2, children: [
      Text({ children: [`🔍 选中 ${lastStats.count} 字 · ${lastStats.label}`], color: lastStats.color }),
    ]})
  })
}

